class ParseError(Exception):
    pass


class MTypeError(Exception):
    pass


class MRuntimeError(Exception):
    pass

# Types
class Type:
    __slots__ = ()


class _TInt(Type):
    __slots__ = ()

    def __repr__(self) -> str:
        return "Int"


class _TBool(Type):
    __slots__ = ()

    def __repr__(self) -> str:
        return "Bool"


TINT = _TInt()
TBOOL = _TBool()


class TFun(Type):
    __slots__ = ("dom", "cod")

    def __init__(self, dom: Type, cod: Type) -> None:
        self.dom = dom
        self.cod = cod

    def __repr__(self) -> str:
        return f"({self.dom!r} -> {self.cod!r})"


class TVar(Type):
    __slots__ = ("instance",)

    def __init__(self) -> None:
        self.instance: Type | None = None


# Expressions
class Expr:
    __slots__ = ()


class IntLit(Expr):
    __slots__ = ("raw",)

    def __init__(self, raw: str) -> None:
        self.raw = raw


class BoolLit(Expr):
    __slots__ = ("val",)

    def __init__(self, val: bool) -> None:
        self.val = val


class Var(Expr):
    __slots__ = ("name",)

    def __init__(self, name: str) -> None:
        self.name = name


class Lam(Expr):
    __slots__ = ("param", "body")

    def __init__(self, param: str, body: Expr) -> None:
        self.param = param
        self.body = body


class App(Expr):
    __slots__ = ("fn", "arg")

    def __init__(self, fn: Expr, arg: Expr) -> None:
        self.fn = fn
        self.arg = arg


class BinOp(Expr):
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left: Expr, right: Expr) -> None:
        self.op = op
        self.left = left
        self.right = right


class If(Expr):
    __slots__ = ("cond", "then_br", "else_br")

    def __init__(self, cond: Expr, then_br: Expr, else_br: Expr) -> None:
        self.cond = cond
        self.then_br = then_br
        self.else_br = else_br


class Let(Expr):
    __slots__ = ("name", "ann", "rhs", "body")

    def __init__(self, name: str, ann: Type | None, rhs: Expr, body: Expr) -> None:
        self.name = name
        self.ann = ann
        self.rhs = rhs
        self.body = body


class LetRec(Expr):
    __slots__ = ("name", "ann", "rhs", "body")

    def __init__(self, name: str, ann: Type, rhs: Lam, body: Expr) -> None:
        self.name = name
        self.ann = ann
        self.rhs = rhs
        self.body = body


class Anno(Expr):
    __slots__ = ("expr", "ann")

    def __init__(self, expr: Expr, ann: Type) -> None:
        self.expr = expr
        self.ann = ann

