import os
import sys

sys.set_int_max_str_digits(0)

_ROOT = os.path.dirname(os.path.realpath(__file__))
if _ROOT not in sys.path:
    sys.path.insert(0, _ROOT)

from mc.compiler import compile_program
from mc.errors import MRuntimeError, MTypeError, ParseError
from mc.lexer import tokenize
from mc.parser import parse
from mc.typecheck import typecheck
from mc.vm import Closure, run_vm


def format_value(val: object) -> str:
    vt = type(val)
    if vt is int:
        return str(val)
    if vt is bool:
        return "True" if val else "False"
    if vt is Closure:
        return "<function>"
    raise AssertionError(f"Unexpected runtime value: {val!r}")


def execute_bytes(raw_bytes: bytes) -> tuple[str, int]:
    try:
        kinds, vals = tokenize(raw_bytes)
        ast = parse(kinds, vals)
        typecheck(ast)
        proto = compile_program(ast)
        val = run_vm(proto)
        return format_value(val), 0
    except ParseError as e:
        return f"ParseError: {e}" if str(e) else "ParseError", 1
    except MTypeError as e:
        return f"TypeError: {e}" if str(e) else "TypeError", 1
    except MRuntimeError as e:
        return f"RuntimeError: {e}" if str(e) else "RuntimeError", 1


def main() -> None:
    if len(sys.argv) != 3 or sys.argv[1] != "run":
        sys.stderr.write("Usage: minicore run FILE\n")
        sys.exit(2)

    filepath = sys.argv[2]
    try:
        with open(filepath, "rb") as f:
            raw_bytes = f.read()
    except OSError as e:
        sys.stderr.write(f"Error reading {filepath}: {e}\n")
        sys.exit(2)

    line, code = execute_bytes(raw_bytes)
    sys.stdout.write(line + "\n")
    sys.exit(code)


if __name__ == "__main__":
    main()

