#!/usr/bin/env python3
"""Comprehensive test suite + independent oracle differential fuzzer for /work/minicore."""

import glob
import importlib.machinery
import importlib.util
import os
import random
import re
import subprocess
import sys
import tempfile
import time

sys.set_int_max_str_digits(0)
ROOT = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
sys.path.insert(0, ROOT)

_loader = importlib.machinery.SourceFileLoader("minicore_cli", os.path.join(ROOT, "minicore"))
_spec = importlib.util.spec_from_loader("minicore_cli", _loader)
assert _spec is not None
minicore_mod = importlib.util.module_from_spec(_spec)
_loader.exec_module(minicore_mod)
execute_bytes = minicore_mod.execute_bytes


def check_case(src: str | bytes, expected: str, label: str = "") -> None:
    raw = src.encode("utf-8") if isinstance(src, str) else src
    out, code = execute_bytes(raw)
    exp_code = 1 if expected in ("ParseError", "TypeError", "RuntimeError") else 0
    if out != expected or code != exp_code:
        raise AssertionError(
            f"FAIL [{label}]:\n  src: {src!r}\n  got: {out!r} (exit={code})\n  exp: {expected!r} (exit={exp_code})"
        )


def check_subprocess(raw: bytes, expected: str, label: str = "") -> None:
    with tempfile.NamedTemporaryFile("wb", suffix=".mc", delete=False) as f:
        f.write(raw)
        path = f.name
    try:
        p = subprocess.run(
            [os.path.join(ROOT, "minicore"), "run", path],
            capture_output=True,
            timeout=5,
        )
        exp_line = (expected + "\n").encode("ascii")
        exp_code = 1 if expected in ("ParseError", "TypeError", "RuntimeError") else 0
        if p.stdout != exp_line or p.returncode != exp_code:
            raise AssertionError(
                f"SUBPROCESS FAIL [{label}]:\n  got stdout={p.stdout!r} exit={p.returncode}\n  exp stdout={exp_line!r} exit={exp_code}\n  stderr={p.stderr!r}"
            )
    finally:
        os.unlink(path)


# ==============================================================================
# 100% Independent Reference Implementation (Zero shared code with mc/!)
# Translated directly from SPEC.md §2, §3, §4, §5, §6.
# ==============================================================================
class _RefParseErr(Exception):
    pass


class _RefTypeErr(Exception):
    pass


class _RefRunErr(Exception):
    pass


def ref_oracle(raw: bytes) -> str:
    try:
        if not raw.isascii():
            raise _RefParseErr()
        s = raw.decode("ascii")

        # §2 Lexer (character-by-character longest-match)
        tokens: list[tuple[str, str]] = []
        i = 0
        n = len(s)
        ws = set(" \t\n\r\f\v")
        kws = {"let", "rec", "in", "if", "then", "else"}
        bad_kws = {"match", "with", "type", "forall", "_"}
        while i < n:
            ch = s[i]
            if ch in ws:
                i += 1
                continue
            if s.startswith("--", i):
                nl = s.find("\n", i + 2)
                i = n if nl == -1 else nl + 1
                continue
            if "0" <= ch <= "9":
                j = i + 1
                while j < n and "0" <= s[j] <= "9":
                    j += 1
                tokens.append(("INT", s[i:j]))
                i = j
                continue
            if ("a" <= ch <= "z") or ch == "_":
                j = i + 1
                while j < n and (("a" <= s[j] <= "z") or ("A" <= s[j] <= "Z") or ("0" <= s[j] <= "9") or s[j] == "_"):
                    j += 1
                w = s[i:j]
                if w in bad_kws:
                    raise _RefParseErr()
                if w in kws:
                    tokens.append((w, w))
                else:
                    tokens.append(("IDENT", w))
                i = j
                continue
            if "A" <= ch <= "Z":
                j = i + 1
                while j < n and (("a" <= s[j] <= "z") or ("A" <= s[j] <= "Z") or ("0" <= s[j] <= "9") or s[j] == "_"):
                    j += 1
                w = s[i:j]
                if w in ("True", "False", "Int", "Bool"):
                    tokens.append((w, w))
                else:
                    raise _RefParseErr()
                i = j
                continue
            # Two-char symbols first (longest match)
            if s.startswith("->", i):
                tokens.append(("->", "->"))
                i += 2
            elif s.startswith("//", i):
                tokens.append(("//", "//"))
                i += 2
            elif s.startswith("==", i):
                tokens.append(("==", "=="))
                i += 2
            elif ch in "()/+*%<=:-":
                tokens.append((ch, ch))
                i += 1
            else:
                raise _RefParseErr()
        tokens.append(("EOF", ""))

        # §3 Recursive-descent EBNF parser
        pos = 0

        def peek() -> str:
            return tokens[pos][0]

        def eat(expected: str) -> str:
            nonlocal pos
            if tokens[pos][0] != expected:
                raise _RefParseErr()
            val = tokens[pos][1]
            pos += 1
            return val

        def parse_type():
            t = parse_tatom()
            if peek() == "->":
                eat("->")
                return ("fun", t, parse_type())
            return t

        def parse_tatom():
            tk = peek()
            if tk == "Int":
                eat("Int")
                return ("int",)
            if tk == "Bool":
                eat("Bool")
                return ("bool",)
            if tk == "(":
                eat("(")
                t = parse_type()
                eat(")")
                return t
            raise _RefParseErr()

        def parse_expr():
            tk = peek()
            if tk == "/":
                eat("/")
                x = eat("IDENT")
                eat("->")
                return ("lam", x, parse_expr())
            if tk == "let":
                eat("let")
                if peek() == "rec":
                    eat("rec")
                    f = eat("IDENT")
                    eat(":")
                    ty = parse_type()
                    eat("=")
                    rhs = parse_expr()
                    # Check RHS is lambda possibly wrapped in plain parens
                    u = rhs
                    while u[0] == "paren":
                        u = u[1]
                    if u[0] != "lam":
                        raise _RefParseErr()
                    eat("in")
                    body = parse_expr()
                    return ("letrec", f, ty, u, body)
                else:
                    x = eat("IDENT")
                    ty = None
                    if peek() == ":":
                        eat(":")
                        ty = parse_type()
                    eat("=")
                    rhs = parse_expr()
                    eat("in")
                    body = parse_expr()
                    return ("let", x, ty, rhs, body)
            if tk == "if":
                eat("if")
                c = parse_expr()
                eat("then")
                t = parse_expr()
                eat("else")
                e = parse_expr()
                return ("if", c, t, e)
            return parse_cmp()

        def parse_cmp():
            left = parse_add()
            if peek() in ("==", "<"):
                op = eat(peek())
                right = parse_add()
                return ("bin", op, left, right)
            return left

        def parse_add():
            left = parse_mul()
            while peek() in ("+", "-"):
                op = eat(peek())
                left = ("bin", op, left, parse_mul())
            return left

        def parse_mul():
            left = parse_app()
            while peek() in ("*", "//", "%"):
                op = eat(peek())
                left = ("bin", op, left, parse_app())
            return left

        def parse_app():
            fn = parse_atom()
            while peek() in ("IDENT", "INT", "True", "False", "("):
                fn = ("app", fn, parse_atom())
            return fn

        def parse_atom():
            tk = peek()
            if tk == "IDENT":
                return ("var", eat("IDENT"))
            if tk == "INT":
                return ("int", int(eat("INT")))
            if tk == "True":
                eat("True")
                return ("bool", True)
            if tk == "False":
                eat("False")
                return ("bool", False)
            if tk == "(":
                eat("(")
                e = parse_expr()
                if peek() == ":":
                    eat(":")
                    ty = parse_type()
                    eat(")")
                    return ("anno", e, ty)
                eat(")")
                return ("paren", e)
            raise _RefParseErr()

        ast = parse_expr()
        eat("EOF")

        # §4 Typechecker
        next_tv = 0
        subst: dict[int, tuple] = {}

        def fresh():
            nonlocal next_tv
            next_tv += 1
            return ("tv", next_tv)

        def deref(t):
            while t[0] == "tv" and t[1] in subst:
                t = subst[t[1]]
            return t

        def occ(v_id: int, t) -> bool:
            t = deref(t)
            if t[0] == "tv":
                return t[1] == v_id
            if t[0] == "fun":
                return occ(v_id, t[1]) or occ(v_id, t[2])
            return False

        def unify(a, b):
            a, b = deref(a), deref(b)
            if a == b:
                return
            if a[0] == "tv":
                if occ(a[1], b):
                    raise _RefTypeErr()
                subst[a[1]] = b
            elif b[0] == "tv":
                if occ(b[1], a):
                    raise _RefTypeErr()
                subst[b[1]] = a
            elif a[0] == "fun" and b[0] == "fun":
                unify(a[1], b[1])
                unify(a[2], b[2])
            else:
                raise _RefTypeErr()

        def tc(e, env: dict[str, tuple]):
            tag = e[0]
            if tag == "paren":
                return tc(e[1], env)
            if tag == "int":
                return ("int",)
            if tag == "bool":
                return ("bool",)
            if tag == "var":
                if e[1] not in env:
                    raise _RefTypeErr()
                return env[e[1]]
            if tag == "lam":
                tv = fresh()
                e2 = dict(env)
                e2[e[1]] = tv
                return ("fun", tv, tc(e[2], e2))
            if tag == "app":
                tf = tc(e[1], env)
                ta = tc(e[2], env)
                tr = fresh()
                unify(tf, ("fun", ta, tr))
                return tr
            if tag == "bin":
                unify(tc(e[2], env), ("int",))
                unify(tc(e[3], env), ("int",))
                return ("bool",) if e[1] in ("==", "<") else ("int",)
            if tag == "if":
                unify(tc(e[1], env), ("bool",))
                t1 = tc(e[2], env)
                t2 = tc(e[3], env)
                unify(t1, t2)
                return t1
            if tag == "anno":
                unify(tc(e[1], env), e[2])
                return e[2]
            if tag == "let":
                _, x, ty, rhs, body = e
                trhs = tc(rhs, env)
                if ty is not None:
                    unify(trhs, ty)
                    trhs = ty
                e2 = dict(env)
                e2[x] = trhs
                return tc(body, e2)
            if tag == "letrec":
                _, f, ty, rhs, body = e
                e2 = dict(env)
                e2[f] = ty
                unify(tc(rhs, e2), ty)
                return tc(body, e2)
            raise AssertionError(e)

        tc(ast, {})

        # §5 Evaluator
        steps = 0

        def ev(e, rho: dict[str, object]):
            nonlocal steps
            steps += 1
            if steps > 40000:
                raise TimeoutError()
            tag = e[0]
            if tag == "paren" or tag == "anno":
                return ev(e[1], rho)
            if tag == "int" or tag == "bool":
                return e[1]
            if tag == "var":
                return rho[e[1]]
            if tag == "lam":
                return ("clos", e[1], e[2], dict(rho))
            if tag == "app":
                c = ev(e[1], rho)
                v = ev(e[2], rho)
                assert isinstance(c, tuple) and c[0] == "clos"
                r2 = dict(c[3])
                r2[c[1]] = v
                return ev(c[2], r2)
            if tag == "bin":
                op = e[1]
                n1 = ev(e[2], rho)
                n2 = ev(e[3], rho)
                assert type(n1) is int and type(n2) is int
                if op == "+":
                    return n1 + n2
                if op == "-":
                    return n1 - n2
                if op == "*":
                    return n1 * n2
                if op == "//":
                    if n2 == 0:
                        raise _RefRunErr()
                    return n1 // n2
                if op == "%":
                    if n2 == 0:
                        raise _RefRunErr()
                    return n1 % n2
                if op == "==":
                    return n1 == n2
                if op == "<":
                    return n1 < n2
            if tag == "if":
                c = ev(e[1], rho)
                assert type(c) is bool
                return ev(e[2] if c else e[3], rho)
            if tag == "let":
                _, x, _, rhs, body = e
                v1 = ev(rhs, rho)
                r2 = dict(rho)
                r2[x] = v1
                return ev(body, r2)
            if tag == "letrec":
                _, f, _, rhs, body = e
                r2 = dict(rho)
                clos = ("clos", rhs[1], rhs[2], r2)
                r2[f] = clos
                return ev(body, r2)
            raise AssertionError(e)

        val = ev(ast, {})
        if isinstance(val, tuple) and val[0] == "clos":
            return "<function>"
        if type(val) is bool:
            return "True" if val else "False"
        return str(val)
    except _RefParseErr:
        return "ParseError"
    except _RefTypeErr:
        return "TypeError"
    except _RefRunErr:
        return "RuntimeError"


# ==============================================================================
# Deterministic Specification Unit Tests
# ==============================================================================
def test_examples() -> None:
    files = sorted(glob.glob(os.path.join(ROOT, "spec/examples/*.mc")))
    assert len(files) == 20
    for mc_file in files:
        raw = open(mc_file, "rb").read()
        exp = open(mc_file[:-3] + ".expected", "r").read().rstrip("\n")
        check_subprocess(raw, exp, mc_file)
    print("  [PASS] 20/20 spec/examples via subprocess")


def test_worked_examples_sec7() -> None:
    cases = [
        ("1 + 2 * 3 - 4", "3"),
        ("10 - 3 - 2", "5"),
        ("(0 - 7) // 2", "-4"),
        ("(0 - 7) % 2", "1"),
        ("2 * 3 == 6", "True"),
        ("(/x -> /y -> x - y) 10 3", "7"),
        ("let add = /x -> /y -> x + y in add 1", "<function>"),
        ("let k = 10 in let f = /x -> x + k in\n  let k = 20 in f 1", "11"),
        (
            "let rec fact : Int -> Int =\n  /n -> if n < 1 then 1 else n * fact (n - 1)\nin fact 25",
            "15511210043330985984000000",
        ),
        ("let id = /x -> x in\n  if id True then id 1 else 2", "TypeError"),
        ("if True then 1 else False", "TypeError"),
        ("/x -> x x", "TypeError"),
        ("let f : Int -> Int = /x -> x in f True", "TypeError"),
        ("nope", "TypeError"),
        ("1 < 2 < 3", "ParseError"),
        ("let rec f = /x -> x in f", "ParseError"),
        ("f /x -> x", "ParseError"),
        ("(1, 2)", "ParseError"),
        ("let z = 0 in 10 // z", "RuntimeError"),
        ("if False then 1 // 0 else 2", "2"),
        ("if True then 1 // 0 else False", "TypeError"),
    ]
    for i, (src, exp) in enumerate(cases):
        check_case(src, exp, f"sec7_{i}")
    print(f"  [PASS] {len(cases)} SPEC §7 worked examples")


def test_lexical_rules() -> None:
    check_subprocess("café".encode("utf-8"), "ParseError", "utf8_ident")
    check_subprocess("-- café\n1 + 1".encode("utf-8"), "ParseError", "utf8_comment")
    check_subprocess("-- 🚀\n42".encode("utf-8"), "ParseError", "emoji_comment")
    check_subprocess(b"\xef\xbb\xbf1 + 1", "ParseError", "utf8_bom")
    check_subprocess(b"1 + 1 -- \x80\n", "ParseError", "raw_0x80_in_comment")
    check_subprocess(b"\xff", "ParseError", "raw_0xff")

    for b in [0x00, 0x01, 0x07, 0x08, 0x0E, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F, 0x7F]:
        check_case(bytes([ord("1"), b, ord("+"), ord("2")]), "ParseError", f"ctrl_{b:#x}")

    check_case(" \t\n\r\f\v1 \t\n\r\f\v+ \t\n\r\f\v2 \t\n\r\f\v", "3", "all_ws")
    check_case("", "ParseError", "empty")
    check_case("   \t\n\r\f\v  ", "ParseError", "ws_only")
    check_case("-- only comment", "ParseError", "comment_only_no_nl")
    check_case("-- only comment\n", "ParseError", "comment_only_nl")

    check_case("1--1", "1", "1--1")
    check_case("1---1", "1", "1---1")
    check_case("1-->2", "1", "1-->2")
    check_case("1-- comment no newline at eof", "1", "comment_eof")
    check_case("1-- comment\r\n+ 2", "3", "crlf_comment")
    check_case("True--False", "True", "True--False")

    check_case("12abc", "TypeError", "12abc_is_type_error_not_parse_error")
    check_case("let abc = 5 in 12abc", "TypeError", "12abc_bound")
    check_case("12True", "TypeError", "12True")
    check_case("12Int", "ParseError", "12Int")
    check_case("(/x->x)42", "42", "no_spaces_app")
    check_case("007", "7", "leading_zeros")
    check_case("0000", "0", "all_zeros")
    check_case("9007199254740993 == 9007199254740992", "False", "past_2_53")
    check_case("18446744073709551617 == 18446744073709551616", "False", "past_2_64")
    big_num = "9" * 10000
    check_case(f"{big_num} - {big_num}", "0", "10k_digit_literal")
    check_subprocess((big_num + " + 1").encode("ascii"), "1" + "0" * 10000, "10k_digit_out")

    check_case("_", "ParseError", "lone_underscore_expr")
    check_case("/_ -> 1", "ParseError", "lone_underscore_lam")
    check_case("let _ = 1 in 2", "ParseError", "lone_underscore_let")
    check_case("let rec _ : Int -> Int = /x -> x in 1", "ParseError", "lone_underscore_rec")
    check_case("let __ = 7 in __", "7", "double_underscore")
    check_case("let _x = 8 in _x", "8", "_x")
    check_case("let _0 = 9 in _0", "9", "_0")
    check_case("let _True = 10 in _True", "10", "_True")
    check_case("let a_B_0 = 11 in a_B_0", "11", "mixed_case_ident")

    for kw in ["let", "rec", "in", "if", "then", "else", "match", "with", "type", "forall"]:
        check_case(kw, "ParseError", f"kw_alone_{kw}")
        check_case(f"/{kw} -> 1", "ParseError", f"kw_param_{kw}")
