def test_syntax_and_untyped_fuzz(num_programs: int = 3000) -> None:
    rng = random.Random(12345)
    toks_pool = [
        "0", "1", "07", "42", "True", "False", "Int", "Bool",
        "x", "y", "_a", "f", "let", "rec", "in", "if", "then", "else",
        "match", "_", "Foo", "/", "->", "(", ")", "+", "-", "*", "//", "%", "==", "<", "=", ":", "--cmt\n",
    ]
    vars_pool = ["x", "y", "z", "f", "g", "_1"]

    def gen_type(d: int) -> str:
        if d <= 0 or rng.random() < 0.65:
            return rng.choice(["Int", "Bool"])
        return f"({gen_type(d - 1)} -> {gen_type(d - 1)})"

    def gen_raw_expr(d: int, bound: list[str]) -> str:
        if d <= 0:
            return rng.choice(["0", "1", "7", "True", "False"] + bound)
        k = rng.randint(0, 10)
        if k == 0:
            v = rng.choice(vars_pool)
            return f"/{v} -> {gen_raw_expr(d - 1, bound + [v])}"
        if k == 1:
            v = rng.choice(vars_pool)
            ann = f" : {gen_type(2)}" if rng.random() < 0.4 else ""
            return f"let {v}{ann} = {gen_raw_expr(d - 1, bound)} in {gen_raw_expr(d - 1, bound + [v])}"
        if k == 2:
            f, p = rng.choice(vars_pool), rng.choice(vars_pool)
            rhs = f"/{p} -> {gen_raw_expr(d - 1, bound + [p])}"
            if rng.random() < 0.25:
                rhs = f"({rhs})"
            elif rng.random() < 0.2:
                # Deliberately sometimes invalid RHS to test letrec parser rule!
                rhs = gen_raw_expr(d - 1, bound)
            return f"let rec {f} : {gen_type(2)} = {rhs} in {gen_raw_expr(d - 1, bound + [f])}"
        if k == 3:
            return f"if {gen_raw_expr(d - 1, bound)} then {gen_raw_expr(d - 1, bound)} else {gen_raw_expr(d - 1, bound)}"
        if k in (4, 5):
            op = rng.choice(["+", "-", "*", "//", "%", "==", "<"])
            l = gen_raw_expr(d - 1, bound)
            r = gen_raw_expr(d - 1, bound)
            if rng.random() < 0.7:
                l = f"({l})"
            if rng.random() < 0.7:
                r = f"({r})"
            return f"{l} {op} {r}"
        if k == 6:
            return f"({gen_raw_expr(d - 1, bound)}) ({gen_raw_expr(d - 1, bound)})"
        if k == 7:
            return f"({gen_raw_expr(d - 1, bound)} : {gen_type(2)})"
        if k == 8:
            # Pure token soup for lexer/parser stress
            return "".join(rng.choice(toks_pool) + (" " if rng.random() < 0.5 else "") for _ in range(rng.randint(1, 10)))
        return f"({gen_raw_expr(d - 1, bound)})"

    counts: dict[str, int] = {}
    tested = 0
    while tested < num_programs:
        src = gen_raw_expr(rng.randint(1, 4), [])
        raw = src.encode("ascii")
        try:
            exp = ref_oracle(raw)
        except TimeoutError:
            continue
        check_case(raw, exp, f"syntax_fuzz_{tested}")
        k = exp if exp in ("ParseError", "TypeError", "RuntimeError", "<function>", "True", "False") else "Int"
        counts[k] = counts.get(k, 0) + 1
        tested += 1
    print(f"  [PASS] {num_programs} syntax/untyped oracle fuzz tests! Outcomes: {counts}")


