# Fuzzer 2: Type-Directed Well-Typed Program Generator (Deep Closures/Shadowing)
# ==============================================================================
def test_well_typed_fuzz(num_programs: int = 3000) -> None:
    rng = random.Random(99999)
    names = ["x", "y", "z", "a", "b", "f", "g", "_k"]

    def ty_str(t) -> str:
        if t == "Int" or t == "Bool":
            return t
        return f"({ty_str(t[1])} -> {ty_str(t[2])})"

    def rand_ty(d: int = 2):
        if d <= 0 or rng.random() < 0.65:
            return rng.choice(["Int", "Bool"])
        return ("->", rand_ty(d - 1), rand_ty(d - 1))

    def gen_typed(target_ty, env: list[tuple[str, object]], d: int, need_atom: bool = False) -> str:
        # Collect in-scope vars matching target_ty (mindful of shadowing: rightmost wins!)
        visible: dict[str, object] = {}
        for k, t in env:
            visible[k] = t
        matching_vars = [k for k, t in visible.items() if t == target_ty]

        if d <= 0:
            if matching_vars and rng.random() < 0.7:
                return rng.choice(matching_vars)
            if target_ty == "Int":
                v = rng.randint(-15, 15)
                return str(v) if v >= 0 else f"(0 - {-v})"
            if target_ty == "Bool":
                return rng.choice(["True", "False"])
            # Function type ("->", dom, cod)
            _, dom, cod = target_ty
            p = rng.choice(names)
            body = gen_typed(cod, env + [(p, dom)], 0, False)
            return f"(/{p} -> {body})"

        if need_atom:
            if matching_vars and rng.random() < 0.4:
                return rng.choice(matching_vars)
            inner = gen_typed(target_ty, env, d - 1, False)
            if rng.random() < 0.25:
                return f"({inner} : {ty_str(target_ty)})"
            return f"({inner})"

        choice = rng.randint(0, 7)

        if choice == 0 and matching_vars:
            return rng.choice(matching_vars)

        if choice == 1:
            # if-then-else
            c = gen_typed("Bool", env, d - 1, False)
            t = gen_typed(target_ty, env, d - 1, False)
            e = gen_typed(target_ty, env, d - 1, False)
            return f"if {c} then {t} else {e}"

        if choice == 2:
            # let with intentional variable shadowing!
            x = rng.choice(names)
            xt = rand_ty(1)
            rhs = gen_typed(xt, env, d - 1, False)
            ann = f" : {ty_str(xt)}" if rng.random() < 0.4 else ""
            body = gen_typed(target_ty, env + [(x, xt)], d - 1, False)
            return f"let {x}{ann} = {rhs} in {body}"

        if choice == 3:
            # let rec (either countdown recursion on Int -> Int or general function)
            fn_name = rng.choice(names)
            p_name = rng.choice([nm for nm in names if nm != fn_name])
            if rng.random() < 0.5:
                ft = ("->", "Int", "Int")
                step_expr = gen_typed("Int", env + [(fn_name, ft), (p_name, "Int")], max(0, d - 2), True)
                rhs = f"/{p_name} -> if {p_name} < 1 then 1 else ({fn_name} ({p_name} - 1)) + {step_expr}"
            else:
                dom, cod = rand_ty(1), rand_ty(1)
                ft = ("->", dom, cod)
                rhs = f"/{p_name} -> {gen_typed(cod, env + [(p_name, dom)], d - 1, False)}"
            if rng.random() < 0.35:
                rhs = f"(({rhs}))"
            body = gen_typed(target_ty, env + [(fn_name, ft)], d - 1, False)
            return f"let rec {fn_name} : {ty_str(ft)} = {rhs} in {body}"

        if choice == 4:
            # Function application!
            arg_ty = rand_ty(1)
            fn_expr = gen_typed(("->", arg_ty, target_ty), env, d - 1, True)
            arg_expr = gen_typed(arg_ty, env, d - 1, True)
            return f"{fn_expr} {arg_expr}"

        if target_ty == "Int":
            op = rng.choice(["+", "-", "*", "//", "%"])
            l = gen_typed("Int", env, d - 1, True)
            r = gen_typed("Int", env, d - 1, True)
            return f"{l} {op} {r}"

        if target_ty == "Bool":
            op = rng.choice(["==", "<"])
            l = gen_typed("Int", env, d - 1, True)
            r = gen_typed("Int", env, d - 1, True)
            return f"{l} {op} {r}"

        # target_ty is ("->", dom, cod)
        _, dom, cod = target_ty
        p = rng.choice(names)
        body = gen_typed(cod, env + [(p, dom)], d - 1, False)
        return f"/{p} -> {body}"

    counts: dict[str, int] = {}
    tested = 0
    while tested < num_programs:
        tgt = rng.choice(["Int", "Int", "Bool", ("->", "Int", "Int")])
        src = gen_typed(tgt, [], rng.randint(2, 4), False)
        raw = src.encode("ascii")
        try:
            exp = ref_oracle(raw)
        except TimeoutError:
            continue
        assert exp not in ("ParseError", "TypeError"), f"Generator produced invalid program:\n{src}\n->{exp}"
        check_case(raw, exp, f"wt_fuzz_{tested}")
        k = exp if exp in ("RuntimeError", "<function>", "True", "False") else "Int"
        counts[k] = counts.get(k, 0) + 1
        tested += 1
    print(f"  [PASS] {num_programs} well-typed closure/shadowing oracle fuzz tests! Outcomes: {counts}")


